create or replace function public.create_organization(p_name text, p_slug text, p_timezone text default 'Africa/Cairo') returns public.organizations language plpgsql security invoker set search_path = public, pg_catalog as $$ declare created_org public.organizations; begin if (select auth.uid()) is null then raise exception 'authentication_required'; end if; if length(trim(p_name)) < 2 or length(trim(p_name)) > 120 then raise exception 'invalid_organization_name'; end if; if p_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' then raise exception 'invalid_organization_slug'; end if; if length(p_timezone) < 1 or length(p_timezone) > 64 then raise exception 'invalid_timezone'; end if; insert into public.organizations (name, slug, owner_id, timezone) values (trim(p_name), lower(trim(p_slug)), (select auth.uid()), p_timezone) returning * into created_org; insert into public.organization_members (organization_id, user_id, role) values (created_org.id, (select auth.uid()), 'owner'); return created_org; end; $$;
revoke all on function public.create_organization(text, text, text) from public;
revoke all on function public.create_organization(text, text, text) from anon;
grant execute on function public.create_organization(text, text, text) to authenticated;
